pointLocator.script:
time_polling_min = 1;
time_polling_seg = time_polling_min * 60;
time_polling_ms = time_polling_seg * 1000;

if(comm_status.time == null){
    return(0.0);
}else{
    if(Date.now() - comm_status.time > time_polling_ms) 
    {
        return(0.0);
    }
    else 
    {
        return(comm_status.value ? 1.0 : 0.0);
    }
}
